using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Security.Cryptography;using System.Text.Json;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Xunit;
namespace AiCare.Tests;
[Collection("Postgres regression")]public sealed class SensitiveOperationStepUpRegressionTests(PostgresRegressionFactory factory):IClassFixture<PostgresRegressionFactory>{[Fact]public async Task SensitiveActionRequiresValidSessionBoundTotpGrantAndEventsAreImmutable(){await factory.EnsureClinicalSeedAsync();var name=$"stepup.{Guid.NewGuid():N}";using(var s=factory.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<CareDbContext>();db.AppUsers.Add(new AppUser(Guid.NewGuid(),name,$"{name}@aicare.local",PasswordHasher.HashPassword("Admin123!"),UserRole.CareManager,true,TenantDefaults.OrganizationId,TenantDefaults.BranchId));await db.SaveChangesAsync();}var login=await factory.CreateClient().PostAsJsonAsync("/api/auth/login",new{userName=name,password="Admin123!",mfaCode=(string?)null});login.EnsureSuccessStatusCode();var token=JsonDocument.Parse(await login.Content.ReadAsStringAsync()).RootElement.GetProperty("token").GetString()!;var client=factory.CreateClient();client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);var enroll=await client.PostAsync("/api/security/mfa/enroll",null);enroll.EnsureSuccessStatusCode();var secret=JsonDocument.Parse(await enroll.Content.ReadAsStringAsync()).RootElement.GetProperty("secret").GetString()!;Assert.Equal(HttpStatusCode.OK,(await client.PostAsJsonAsync("/api/security/mfa/enroll/verify",new{code=Totp(secret)})).StatusCode);var report=new{name="Step-up regression",format="CSV"};Assert.Equal(HttpStatusCode.Forbidden,(await client.PostAsJsonAsync("/api/phase1/reports/generate",report)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync("/api/security/step-up/challenge",new{purpose="export",operationScope="report.generate",code="000000",evidence="Regression"})).StatusCode);var grant=await client.PostAsJsonAsync("/api/security/step-up/challenge",new{purpose="export",operationScope="report.generate",code=Totp(secret),evidence="Regression"});Assert.Equal(HttpStatusCode.OK,grant.StatusCode);var json=JsonDocument.Parse(await grant.Content.ReadAsStringAsync()).RootElement;Assert.True(json.GetProperty("expiresAt").GetDateTimeOffset()<=DateTimeOffset.UtcNow.AddMinutes(11));Assert.Equal(HttpStatusCode.OK,(await client.PostAsJsonAsync("/api/phase1/reports/generate",report)).StatusCode);using var verify=factory.Services.CreateScope();var db2=verify.ServiceProvider.GetRequiredService<CareDbContext>();Assert.True(await db2.AuditEvents.AnyAsync(x=>x.Action=="security.step_up_granted"));Assert.True(await db2.Database.SqlQueryRaw<int>("select 1 as \"Value\" from auth_step_up_events where event_type='Required' limit 1").AnyAsync());await Assert.ThrowsAnyAsync<Exception>(()=>db2.Database.ExecuteSqlRawAsync("update auth_step_up_events set detail='changed' where event_type='Used'"));}
static string Totp(string secret){const string a="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";var o=new List<byte>();int b=0,n=0;foreach(var ch in secret){b=(b<<5)|a.IndexOf(ch);n+=5;if(n>=8){o.Add((byte)(b>>(n-8)));n-=8;b&=(1<<n)-1;}}var c=DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30;var x=BitConverter.GetBytes(c);if(BitConverter.IsLittleEndian)Array.Reverse(x);using var h=new HMACSHA1(o.ToArray());var z=h.ComputeHash(x);var i=z[^1]&15;var v=(((z[i]&127)<<24)|((z[i+1]&255)<<16)|((z[i+2]&255)<<8)|(z[i+3]&255))%1_000_000;return v.ToString("D6");}}
